SELECT 'gongkao', '星期日期问题', 'kp-xc-quantity-math-operation-calendar', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "星期日期问题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "星期日期问题围绕闰年平年和星期推算展开，核心是掌握闰年判定规则和星期的周期性。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、知识要点"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "闰年判定：能被4整除且不能被100整除，或能被400整除"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "闰年366天（2月29天），平年365天（2月28天）"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "星期周期：每7天一个循环，365÷7=52余1，平年星期+1；366÷7=52余2，闰年星期+2"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "月份天数：1/3/5/7/8/10/12月31天，4/6/9/11月30天，2月28或29天"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "日期范围统计：某月有几个星期几的问题，用整除和余数分析"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、解题方法"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "闰年判定法：先看能否被400整除，再看能否被4整除但不能被100整除"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "星期推算法：计算两个日期之间相差的天数，除以7看余数"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "周期分析法：找出循环周期，用总天数除以周期取余"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列表法：把月份天数列出来逐月推算"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记整百年要能被400整除才是闰年（如1900年不是闰年）"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "跨月推算时月份天数算错"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "星期推算时余数方向搞反（加还是减）"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "星期日期问题难度不高但容易粗心。建议练习闰年判定和跨月星期推算两类题型。"}]}]}]}$$ AS jsonb), NULL, '数量关系-数学运算-星期日期问题的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "数学运算", "星期日期问题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_calendar", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
